const input = items[0].json || {};
const action = String(input.action || 'list').toLowerCase();
const limit = Math.min(Math.max(parseInt(input.limit || input.count || 10, 10) || 10, 1), 25);
const telegramChatId = String(input.telegramChatId || input.chatId || 'unknown');
const requestType = String(input.requestType || 'metadata').toLowerCase();
const emailNumber = Number(input.emailNumber || input.number || 0);
const query = String(input.query || input.search || '').trim();
const onlyUnread = input.onlyUnread !== false;
const todayOnly = Boolean(input.todayOnly || /today|heute/i.test(String(input.requestType || input.query || '')));
function berlinDateParts(date) {
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(date);
  const o = Object.fromEntries(parts.map(p => [p.type, p.value]));
  return `${o.year}-${o.month}-${o.day}`;
}
function berlinOffset(date) {
  const part = new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/Berlin', timeZoneName: 'shortOffset' }).formatToParts(date).find(p => p.type === 'timeZoneName');
  const m = String(part?.value || 'GMT+1').match(/GMT([+-])(\d{1,2})(?::(\d{2}))?/);
  if (!m) return '+01:00';
  return `${m[1]}${m[2].padStart(2,'0')}:${(m[3] || '00').padStart(2,'0')}`;
}
let filters = [];
if (onlyUnread) filters.push('isRead eq false');
if (todayOnly) {
  const d = new Date();
  const ymd = berlinDateParts(d);
  const off = berlinOffset(d);
  filters.push(`receivedDateTime ge ${ymd}T00:00:00${off}`);
  filters.push(`receivedDateTime le ${ymd}T23:59:59${off}`);
}
let url = `https://graph.microsoft.com/v1.0/me/mailFolders/Inbox/messages?$top=${limit}&$select=id,conversationId,subject,from,receivedDateTime,isRead,hasAttachments,webLink,bodyPreview&$orderby=receivedDateTime%20desc`;
if (filters.length) url += `&$filter=${encodeURIComponent(filters.join(' and '))}`;
if (query) url = `https://graph.microsoft.com/v1.0/me/messages?$top=${limit}&$search=${encodeURIComponent('"' + query.replace(/"/g, '') + '"')}&$select=id,conversationId,subject,from,receivedDateTime,isRead,hasAttachments,webLink,bodyPreview`;
return [{ json: { action, limit, telegramChatId, requestType, emailNumber, query, graphUrl: url } }];

function cleanError(value) {
  if (!value) return 'Unknown error';
  if (typeof value === 'string') return value.slice(0, 600);
  if (value.message) return String(value.message).slice(0, 600);
  return JSON.stringify(value).slice(0, 600);
}
function safeText(value) {
  return String(value ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
function person(mailbox) {
  const e = mailbox?.emailAddress || mailbox || {};
  return { name: e.name || '', email: e.address || '' };
}
function pass(response, extra = {}) {
  return [{ json: { ...extra, response, verificationStatus: 'Passed' } }];
}
function fail(tool, error, action='No Microsoft 365 state was changed.') {
  const msg = cleanError(error);
  return [{ json: { response: `Tool failed: Yes\nTool used: ${tool}\nError message: ${msg}\nAction taken: ${action}\nVerification status: Failed`, toolFailed: true, toolUsed: tool, errorMessage: msg, actionTaken: action, verificationStatus: 'Failed' } }];
}

const source = $('Normalize Context Input').item.json;
const data = items[0].json || {};
if (data.error || data.message?.includes?.('Unauthorized')) return fail('WF_EMAIL_LIST_CONTEXT', data.error || data.message);
const emails = Array.isArray(data.value) ? data.value : (Array.isArray(data) ? data : []);
const numbered = emails.slice(0, source.limit).map((m, idx) => {
  const sender = person(m.from);
  return {
    listNumber: idx + 1,
    message_id: m.id,
    conversationId: m.conversationId || '',
    subject: m.subject || '(no subject)',
    senderName: sender.name,
    senderEmail: sender.email,
    receivedDateTime: m.receivedDateTime || '',
    isRead: Boolean(m.isRead),
    hasAttachments: Boolean(m.hasAttachments),
    webLink: m.webLink || '',
    bodyPreview: m.bodyPreview || '',
    createdAt: new Date().toISOString(),
    telegramChatId: source.telegramChatId
  };
});
const store = $getWorkflowStaticData('global');
store.emailLists = store.emailLists || {};
store.emailLists[source.telegramChatId] = { createdAt: new Date().toISOString(), items: numbered };
const lines = numbered.map(e => `${e.listNumber}. ${e.senderName || e.senderEmail}\nSubject: ${e.subject}\nReceived: ${e.receivedDateTime}\nRead status: ${e.isRead ? 'Read' : 'Unread'}\nAttachments: ${e.hasAttachments ? 'Yes' : 'No'}\nSummary: ${safeText(e.bodyPreview)}`);
return pass(`Emails found: ${numbered.length}\n${lines.join('\n\n')}\nVerification status: Passed`, { emails: numbered, count: numbered.length });

function cleanError(value) {
  if (!value) return 'Unknown error';
  if (typeof value === 'string') return value.slice(0, 600);
  if (value.message) return String(value.message).slice(0, 600);
  return JSON.stringify(value).slice(0, 600);
}
function safeText(value) {
  return String(value ?? '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
function person(mailbox) {
  const e = mailbox?.emailAddress || mailbox || {};
  return { name: e.name || '', email: e.address || '' };
}
function pass(response, extra = {}) {
  return [{ json: { ...extra, response, verificationStatus: 'Passed' } }];
}
function fail(tool, error, action='No Microsoft 365 state was changed.') {
  const msg = cleanError(error);
  return [{ json: { response: `Tool failed: Yes\nTool used: ${tool}\nError message: ${msg}\nAction taken: ${action}\nVerification status: Failed`, toolFailed: true, toolUsed: tool, errorMessage: msg, actionTaken: action, verificationStatus: 'Failed' } }];
}

const source = $('Normalize Context Input').item.json;
const store = $getWorkflowStaticData('global');
const list = store.emailLists?.[source.telegramChatId]?.items || [];
const found = list.find(e => Number(e.listNumber) === Number(source.emailNumber));
if (!found) {
  return pass(`The saved email list expired or Email ${source.emailNumber || ''} was not found. Please list emails again.\nVerification status: Failed`, { found: false, verificationStatus: 'Failed' });
}
return pass(`Email Nr. ${found.listNumber} found.\nSender: ${found.senderName || found.senderEmail}\nSubject: ${found.subject}\nReceived: ${found.receivedDateTime}\nAttachments: ${found.hasAttachments ? 'Yes' : 'No'}\nMessage ID: ${found.message_id}\nVerification status: Passed`, { found: true, email: found, message_id: found.message_id, emailNumber: found.listNumber });
